body.script:
const START =
  "https://raw.githack.com/Bubba7004/minty-proxy-assets/HEAD/games/index-261014.html";

function patch() {
  if (window.__repoLoaderInstalled) return;
  window.__repoLoaderInstalled = true;

  const HTML_NS = "http://www.w3.org/1999/xhtml";

  const RAW_HOSTS = new Set([
    "raw.githack.com",
    "rawcdn.githack.com"
  ]);

  const frameStates = new WeakMap();

  function escapeAttribute(value) {
    return String(value).replace(/[&"<>]/g, (character) => ({
      "&": "&amp;",
      '"': "&quot;",
      "<": "&lt;",
      ">": "&gt;"
    }[character]));
  }

  function escapeText(value) {
    return String(value).replace(/[&<>]/g, (character) => ({
      "&": "&amp;",
      "<": "&lt;",
      ">": "&gt;"
    }[character]));
  }

  function isFrame(element) {
    return Boolean(
      element &&
      element.nodeType === 1 &&
      element.localName &&
      element.localName.toLowerCase() === "iframe" &&
      element.namespaceURI === HTML_NS
    );
  }

  // Convert GitHub-backed jsDelivr URLs to raw.githack URLs.
  function normalizeUrl(value, base = document.baseURI) {
    const url = new URL(value, base);

    if (
      url.protocol === "https:" &&
      url.hostname === "cdn.jsdelivr.net"
    ) {
      const match = url.pathname.match(
        /^\/gh\/([^/]+)\/([^/@]+)(?:@([^/]+))?\/(.+)$/
      );

      if (match) {
        const [, owner, repo, version, path] = match;
        const ref =
          !version || version === "latest"
            ? "HEAD"
            : version;

        return (
          "https://raw.githack.com/" +
          owner + "/" +
          repo + "/" +
          ref + "/" +
          path +
          url.search +
          url.hash
        );
      }
    }

    return url.href;
  }

  function cdnHtml(value) {
    try {
      const url = new URL(normalizeUrl(value));

      if (url.protocol !== "https:") return null;
      if (!RAW_HOSTS.has(url.hostname)) return null;
      if (!/\.html?$/i.test(url.pathname)) return null;

      return url.href;
    } catch {
      return null;
    }
  }

  function rewrite(source) {
    // Rewrite literal URLs for this repository, including
    // URLs found in inline scripts and HTML attributes.
    source = source.replace(
      /https:\/\/cdn\.jsdelivr\.net\/gh\/Bubba7004\/minty-proxy-assets(?:@([^\/\s"'<>`\\]+))?\//gi,
      (match, version) => {
        const ref =
          !version || version === "latest"
            ? "HEAD"
            : version;

        return (
          "https://raw.githack.com/" +
          "Bubba7004/minty-proxy-assets/" +
          ref +
          "/"
        );
      }
    );

    // Best-effort support for common location navigation.
    // This is not a complete JavaScript parser.
    const L =
      String.raw`(?<![\w$.])(?:(?:window|self|top|parent|document)\.)?location`;

    return source
      .replace(
        new RegExp(
          L + String.raw`\.(?:assign|replace)\s*\(`,
          "g"
        ),
        "__go("
      )
      .replace(
        new RegExp(
          L +
          String.raw`(?:\.href)?\s*=(?!=)\s*([^;\n}]+)`,
          "g"
        ),
        "__go($1)"
      );
  }

  async function build(value, signal) {
    const target = cdnHtml(value);

    if (!target) {
      throw new Error("Unsupported HTML URL: " + value);
    }

    const response = await fetch(target, {
      signal: signal
    });

    const text = await response.text();

    if (!response.ok) {
      throw new Error(
        "Failed to load:\n" + target +
        "\n\nHTTP " + response.status +
        "\n\n" + text.slice(0, 800)
      );
    }

    if (
      /^\s*Package size exceeded the configured limit/i.test(text)
    ) {
      throw new Error(text.trim());
    }

    const html = rewrite(text);
    const baseUrl = (response.url || target).split("#")[0];

    // Construct explicitly: do not create an unnamespaced
    // <base> element in the outer SVG/XML document.
    const inject =
      '<base href="' + escapeAttribute(baseUrl) + '">' +
      "<scr" + "ipt>(" +
      patch.toString() +
      ")()</scr" + "ipt>";

    // Put the base and loader before page scripts.
    if (/<head(?:\s[^>]*)?>/i.test(html)) {
      return html.replace(
        /<head(?:\s[^>]*)?>/i,
        (openingHead) => openingHead + inject
      );
    }

    if (/<html(?:\s[^>]*)?>/i.test(html)) {
      return html.replace(
        /<html(?:\s[^>]*)?>/i,
        (openingHtml) =>
          openingHtml + "<head>" + inject + "</head>"
      );
    }

    // Preserve an initial doctype when no head/html exists.
    const doctype = html.match(/^\s*<!doctype[^>]*>/i);

    if (doctype) {
      return (
        doctype[0] +
        inject +
        html.slice(doctype[0].length)
      );
    }

    return inject + html;
  }

  function showError(frame, error) {
    console.error("Repository loader:", error);

    const message =
      error && error.message
        ? error.message
        : String(error);

    frame.srcdoc =
      '<!doctype html><html><head>' +
      '<meta name="viewport" ' +
      'content="width=device-width,initial-scale=1">' +
      '<title>Loading error</title>' +
      '</head><body style="' +
      'margin:0;padding:24px;background:#111;color:#eee;' +
      'font-family:system-ui,sans-serif;">' +
      '<h2>Unable to load the page</h2>' +
      '<pre style="' +
      'white-space:pre-wrap;overflow-wrap:anywhere;">' +
      escapeText(message) +
      '</pre></body></html>';
  }

  function cancelLoad(frame) {
    const state = frameStates.get(frame);

    if (state) {
      state.controller.abort();
      frameStates.delete(frame);
    }
  }

  function fill(frame, value) {
    const url = cdnHtml(value);
    if (!url) return;

    const previous = frameStates.get(frame);
    if (previous && previous.url === url) return;

    cancelLoad(frame);

    const state = {
      url: url,
      controller: new AbortController()
    };

    frameStates.set(frame, state);

    build(url, state.controller.signal)
      .then((html) => {
        if (frameStates.get(frame) !== state) return;

        frame.removeAttribute("src");
        frame.srcdoc = html;
      })
      .catch((error) => {
        if (frameStates.get(frame) !== state) return;
        if (error.name === "AbortError") return;

        frameStates.delete(frame);
        showError(frame, error);
      });
  }

  window.__build = build;
  window.__fill = fill;

  window.__go = function(value) {
    const url = cdnHtml(value);

    if (url && window.parent !== window) {
      window.parent.postMessage(
        {
          __repoLoaderNav: true,
          url: url
        },
        "*"
      );

      return;
    }

    // Normal navigation for destinations not handled here.
    location.href = new URL(value, document.baseURI).href;
  };

  window.addEventListener("message", (event) => {
    const data = event.data;

    if (
      !data ||
      data.__repoLoaderNav !== true ||
      typeof data.url !== "string"
    ) {
      return;
    }

    const url = cdnHtml(data.url);
    if (!url) return;

    // Accept navigation requests only from a direct child.
    for (const frame of document.querySelectorAll("iframe")) {
      if (frame.contentWindow === event.source) {
        fill(frame, url);
        return;
      }
    }
  });

  const srcDescriptor = Object.getOwnPropertyDescriptor(
    HTMLIFrameElement.prototype,
    "src"
  );

  if (
    srcDescriptor &&
    srcDescriptor.get &&
    srcDescriptor.set &&
    srcDescriptor.configurable
  ) {
    Object.defineProperty(
      HTMLIFrameElement.prototype,
      "src",
      {
        configurable: srcDescriptor.configurable,
        enumerable: srcDescriptor.enumerable,

        get() {
          return srcDescriptor.get.call(this);
        },

        set(value) {
          const url = cdnHtml(value);

          if (url) {
            fill(this, url);
            return;
          }

          cancelLoad(this);
          this.removeAttribute("srcdoc");
          srcDescriptor.set.call(this, value);
        }
      }
    );
  }

  const originalSetAttribute =
    Element.prototype.setAttribute;

  Element.prototype.setAttribute = function(name, value) {
    if (
      isFrame(this) &&
      String(name).toLowerCase() === "src"
    ) {
      const url = cdnHtml(value);

      if (url) {
        fill(this, url);
        return;
      }

      cancelLoad(this);
      this.removeAttribute("srcdoc");
    }

    return originalSetAttribute.call(this, name, value);
  };

  function check(frame) {
    if (!isFrame(frame)) return;

    const raw = frame.getAttribute("src");
    if (!raw) return;

    const url = cdnHtml(raw);
    if (!url) return;

    frame.removeAttribute("src");
    fill(frame, url);
  }

  function scan(root) {
    if (!root || root.nodeType !== 1) return;

    if (isFrame(root)) check(root);

    if (root.querySelectorAll) {
      root.querySelectorAll("iframe[src]").forEach(check);
    }
  }

  new MutationObserver((mutations) => {
    for (const mutation of mutations) {
      if (mutation.type === "attributes") {
        check(mutation.target);
      } else {
        mutation.addedNodes.forEach(scan);
      }
    }
  }).observe(document, {
    childList: true,
    subtree: true,
    attributes: true,
    attributeFilter: ["src"]
  });

  scan(document.documentElement);

  document.addEventListener("click", (event) => {
    const element =
      event.target && event.target.nodeType === 1
        ? event.target
        : event.target && event.target.parentElement;

    const anchor =
      element && element.closest
        ? element.closest("a[href]")
        : null;

    if (!anchor) return;

    const url = cdnHtml(anchor.getAttribute("href"));
    if (!url) return;

    event.preventDefault();
    window.__go(url);
  }, true);

  const originalOpen = window.open;

  window.open = function(value, ...rest) {
    const url = value && cdnHtml(value);

    if (url) {
      window.__go(url);
      return null;
    }

    return originalOpen.call(window, value, ...rest);
  };
}

patch();

window.__fill(
  document.getElementById("test"),
  START
);
